import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_id(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            an, bn = int(a), int(b)
            return (an > bn) - (an < bn)
        elif a_num and not b_num:
            return -1
        elif not a_num and b_num:
            return 1
        else:
            return (a > b) - (a < b)

    def compare(v1, v2):
        M1, m1, p1, pre1 = parse(v1)
        M2, m2, p2, pre2 = parse(v2)
        if M1 != M2:
            return -1 if M1 < M2 else 1
        if m1 != m2:
            return -1 if m1 < m2 else 1
        if p1 != p2:
            return -1 if p1 < p2 else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None and pre2 is not None:
            return 1
        if pre1 is not None and pre2 is None:
            return -1
        for i1, i2 in zip(pre1, pre2):
            c = cmp_id(i1, i2)
            if c != 0:
                return c
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1
        return 0

    return sorted(versions, key=functools.cmp_to_key(compare))

